[strategy/guidance/application/responsive-layout/GUID-APP-UI-002-responsive-layout-implementation-guidance.md#container-strategy]

### Container Strategy

Three container variants serve different content width requirements:

```typescript
// src/components/layout/container.tsx

type ContainerVariant = 'default' | 'narrow' | 'wide' | 'fluid';

const containerVariants: Record<ContainerVariant, string> = {
  // Default: max-w-screen-xl — suits portal page content (1280px max)
  default: 'mx-auto w-full max-w-screen-xl px-4 sm:px-6 lg:px-8',
  // Narrow: max-w-2xl — suits forms, articles, single-column content
  narrow: 'mx-auto w-full max-w-2xl px-4 sm:px-6',
  // Wide: max-w-screen-2xl — suits data-heavy dashboards
  wide: 'mx-auto w-full max-w-screen-2xl px-4 sm:px-6 lg:px-8',
  // Fluid: no max-width — full bleed; use only for full-width sections
  fluid: 'w-full px-4 sm:px-6 lg:px-8',
};

export function Container({
  variant = 'default',
  children,
  className,
}: {
  variant?: ContainerVariant;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn(containerVariants[variant], className)}>
      {children}
    </div>
  );
}
```

