[strategy/guidance/application/responsive-layout/GUID-APP-UI-002-responsive-layout-implementation-guidance.md#2-12-column-grid-layout]

### 2. 12-Column Grid Layout

Use CSS Grid for page-level layout:

```tsx
// src/components/layout/page-grid.tsx
export function PageGrid({ children }: { children: React.ReactNode }) {
  return (
    <div className="grid grid-cols-4 gap-4 md:grid-cols-8 lg:grid-cols-12">
      {children}
    </div>
  );
}

// Usage — a content + sidebar layout
export function ClaimDetailLayout() {
  return (
    <Container>
      <PageGrid>
        {/* Main content: full width on mobile, 8/12 cols on lg */}
        <main className="col-span-4 md:col-span-8 lg:col-span-8">
          <ClaimDetail />
        </main>
        {/* Sidebar: full width on mobile, 4/12 cols on lg */}
        <aside className="col-span-4 md:col-span-8 lg:col-span-4">
          <ClaimActions />
        </aside>
      </PageGrid>
    </Container>
  );
}
```

