[strategy/guidance/application/responsive-layout/GUID-APP-UI-002-responsive-layout-implementation-guidance.md#3-flexbox-for-component-level-alignment]

### 3. Flexbox for Component-Level Alignment

Use Flexbox within components for alignment of sub-elements:

```tsx
// ✅ Flexbox for button groups, icon+label combinations, card headers
export function CardHeader({ title, action }: { title: string; action?: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-4">
      <h2 className="text-lg font-semibold">{title}</h2>
      {action && <div className="flex shrink-0 items-center gap-2">{action}</div>}
    </div>
  );
}

// ✅ Flex column on mobile → row at sm: for stacked-to-inline button groups
export function FormActions({ onCancel, onSubmit }: FormActionsProps) {
  return (
    <div className="flex flex-col gap-2 sm:flex-row sm:justify-end">
      <button type="button" onClick={onCancel} className="w-full sm:w-auto">
        Cancel
      </button>
      <button type="submit" onClick={onSubmit} className="w-full sm:w-auto">
        Submit
      </button>
    </div>
  );
}
```

