[strategy/guidance/application/responsive-layout/GUID-APP-UI-002-responsive-layout-implementation-guidance.md#4-responsive-stack-pattern]

### 4. Responsive Stack Pattern

The stack pattern is the foundational mobile-first layout primitive. Elements stack vertically on mobile and arrange horizontally at a defined breakpoint:

```tsx
// src/components/layout/stack.tsx
type StackDirection = 'vertical' | 'horizontal';
type StackBreakpoint = 'sm' | 'md' | 'lg';

const directionClasses: Record<StackDirection, Record<StackBreakpoint, string>> = {
  vertical: {
    sm: 'flex flex-col sm:flex-row',
    md: 'flex flex-col md:flex-row',
    lg: 'flex flex-col lg:flex-row',
  },
  horizontal: {
    sm: 'flex flex-row',
    md: 'flex flex-row',
    lg: 'flex flex-row',
  },
};

export function Stack({
  direction = 'vertical',
  switchAt = 'md',
  gap = 4,
  children,
  className,
}: {
  direction?: StackDirection;
  switchAt?: StackBreakpoint;
  gap?: number;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        directionClasses[direction][switchAt],
        `gap-${gap}`,
        className
      )}
    >
      {children}
    </div>
  );
}
```

