[strategy/guidance/application/responsive-layout/GUID-APP-UI-002-responsive-layout-implementation-guidance.md#6-responsive-table-strategy]

### 6. Responsive Table Strategy

Tables on mobile require a strategy — full-width tables that overflow on small screens are the most common failure:

```tsx
// ✅ Scrollable table wrapper on mobile
export function ResponsiveTableWrapper({ children }: { children: React.ReactNode }) {
  return (
    <div
      className="w-full overflow-x-auto rounded-md border"
      // Announce scrollability to screen readers
      role="region"
      aria-label="Scrollable data table"
      tabIndex={0}
    >
      {children}
    </div>
  );
}

// ✅ Priority columns — hide non-essential columns on mobile
export function ClaimsTableRow({ claim }: { claim: Claim }) {
  return (
    <tr>
      <td>{claim.id}</td>
      <td>{claim.status}</td>
      {/* Hide date on mobile — secondary information */}
      <td className="hidden sm:table-cell">{claim.date}</td>
      {/* Hide provider on mobile — tertiary information */}
      <td className="hidden md:table-cell">{claim.provider}</td>
    </tr>
  );
}
```

