### Use Case 2 — Form Layout (Single Column → Two Column at md)

```tsx
export function ClaimSubmissionForm() {
  return (
    <Container variant="narrow">
      <form className="space-y-6">
        <h1 className="text-2xl font-bold">Submit Claim</h1>

        {/* Single column on mobile, 2 columns at md */}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          <MemberIdInput />
          <DateOfServiceInput />
          <ProviderNpiInput />
          <DiagnosisCodeInput />
        </div>

        {/* Full width — always single column */}
        <NotesTextarea />

        <FormActions />
      </form>
    </Container>
  );
}
```

